package com.nethrion.teams;
import java.util.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.event.*;import org.bukkit.event.inventory.*;
public final class StorageCommand implements CommandExecutor,Listener{
 private final TeamManager teams;private final VaultManager vaults;private static final String TITLE="Team Storage";
 public StorageCommand(TeamManager t,VaultManager v){teams=t;vaults=v;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;Team t=teams.currentTeam(p);if(t==null){p.sendMessage(ChatColor.RED+"You are not in a team.");return true;}List<TeamVault> vs=vaults.teamVaults(t.getId());Inventory inv=Bukkit.createInventory(null,27,TITLE);for(int i=0;i<27;i++){ItemStack lock=new ItemStack(Material.GRAY_STAINED_GLASS_PANE);ItemMeta m=lock.getItemMeta();m.setDisplayName(ChatColor.DARK_GRAY+"Locked");lock.setItemMeta(m);inv.setItem(i,lock);}for(int i=0;i<Math.min(27,vs.size());i++){ItemStack x=new ItemStack(Material.CHEST);ItemMeta m=x.getItemMeta();m.setDisplayName(ChatColor.GOLD+"Chest "+(i+1));m.getPersistentDataContainer().set(new org.bukkit.NamespacedKey("nethrionteams","vault"),org.bukkit.persistence.PersistentDataType.STRING,vs.get(i).id().toString());x.setItemMeta(m);inv.setItem(i,x);}p.openInventory(inv);return true;}
 @EventHandler(ignoreCancelled=true)public void click(InventoryClickEvent e){if(!e.getView().getTitle().equals(TITLE)||!(e.getWhoClicked() instanceof Player p))return;e.setCancelled(true);ItemStack x=e.getCurrentItem();if(x==null||!x.hasItemMeta())return;String id=x.getItemMeta().getPersistentDataContainer().get(new org.bukkit.NamespacedKey("nethrionteams","vault"),org.bukkit.persistence.PersistentDataType.STRING);if(id!=null){try{vaults.open(p,UUID.fromString(id));}catch(Exception ignored){p.sendMessage(ChatColor.RED+"Vault unavailable.");}}}
}
